d=json.load(open('/home/claude/lib/dinler/cc3.json'))
TR=[(r'Endredaktion des Pentateuchs?','Tevrat’ın son redaksiyonu'),(r'Endredaktion des Psalters','Mezmurlar’ın son redaksiyonu'),(r'Endredaktion des Zwölfprophetenbuches','On İki Peygamber’in son redaksiyonu'),(r'Redaktion des deuteronomistischen Geschichtswerke?s','Tesniyeci tarih eserinin redaksiyonu'),(r'Anfertigung der Jesajarolle aus Qumran','Kumran Yeşaya tomarının yazımı'),(r'Endredaktion durch die Stamma.im','Stammaim’in son redaksiyonu'),(r'Datierung der Rezension β','β rivayetinin tarihi'),
 (r'(?i)\bvor (dem )?([^()]+?)\s*(?=\(|$)',r'\2 öncesi '),(r'\bnach (dem )?([^(),]+?)\s*(?=\(|$|,)',r'\2 sonrası '),(r'\bn\. ?Chr\.?|\bA\.?D\.?|C\.E\.','MS'),(r'\bv\. ?Chr\.?|vor Chr\.','MÖ'),(r'\b[Cc]a\.? ?','yak. '),(r'\bum (die Wende vom)?','yak. '),(r'Jahrhunderts?|Jh[sd]?\.?|Jt\.','yy.'),(r'\bvor\b','önce'),(r'\bnach\b','sonra'),(r'\bzwischen (\S+) und','\\1 ile'),(r'\bAnfang( des)?','başı'),(r'\bEnde( des)?','sonu'),(r'\bMitte( des)?','ortası'),(r'(\d)\. Hälfte( des)?',r'\1. yarısı'),(r'Letztes Drittel des','son üçte biri'),
 (r'Endredaktion','son redaksiyon'),(r'Redaktion','redaksiyon'),(r'verschriftlicht','yazıya geçirildi'),(r'Regierungszeit des','saltanatı:'),(r'Späte S[aā]s[aā]nidenzeit','Geç Sâsânî dönemi'),(r'\boder\b','veya'),(r'\bund\b','ve'),(r'früher','öncesi'),(r'umstritten','tartışmalı'),(r'wahrscheinlich','muhtemelen'),(r'bzw\.','veya'),(r'finale Kompilation','son derleme'),(r'Kompilation','derleme'),(r'\bdes\b|\bdem\b|\bder\b|\bvom\b|\bzum\b',''),(r'Anfertigung Jesajarolle aus Qumran','Kumran Yeşaya tomarı'),(r'deuteronomistischen Geschichtswerke?s','Tesniyeci tarih eseri'),(r'Psalters','Mezmurlar'),(r'Pentateuchs?','Tevrat'),(r'Zwölfprophetenbuches','On İki Peygamber'),(r'Kanonisierung','kanonlaşma'),(r'Fertigstellung','tamamlanma'),(r'Grundstock','çekirdek'),(r'christliche Bearbeitung','Hristiyan işlemesi'),(r'Lateinische Übersetzung','Latince çeviri'),(r'Datierung Rezension','rivayet tarihi'),(r'reg\.','hd.'),(r'\bab\b',''),(r'etwa','yak.'),(r'z\. T\. später','kısmen sonra'),(r'Traktate erst','risaleler ancak'),(r'einzelnen',''),(r'Monat','ay'),(r'Regierungsjahres','saltanat yılı'),(r'himjaritische Ära','Himyerî takvim'),(r'Aus saltanatı: sabäischen Königs','Sebe kralı'),(r'seinem Bruder','kardeşi'),(r'himyaritischen Königs','Himyerî kral'),(r'März','Mart'),(r'\s+',' ')]
YER={'Palästina':'Filistin','Syrien':'Suriye','Mesopotamien':'Mezopotamya','Nordmesopotamien':'Kuzey Mezopotamya','Südmesopotamien':'Güney Mezopotamya','Iran':'İran','Ostiran':'Doğu İran','Ost-Iran':'Doğu İran','Rom':'Roma','östlicher Mittelmeerraum':'Doğu Akdeniz','Alexandria':'İskenderiye','Alexandrien':'İskenderiye','Nordafrika':'Kuzey Afrika','Ephesus':'Efes','Ephesos':'Efes','Konstantinopel':'Konstantinopolis','Arabische Halbinsel':'Arap Yarımadası','Ägypten':'Mısır','Babylonien':'Babil','Kleinasien':'Anadolu','Ägäis':'Ege','Äthiopien':'Habeşistan','Antiochien':'Antakya','Korinth':'Korint','Makedonien':'Makedonya','Thrakien':'Trakya','Athen':'Atina','Griechenland':'Yunanistan','Merowingerreich':'Merovenj Krallığı','Berg Qardu':'Kardu Dağı','Caesarea Maritima':'Kayserya','Südfrankreich':'Güney Fransa','Byzanz':'Bizans','Italien':'İtalya','Levante':'Levant','Gallien':'Galya','Hellenistische Diaspora':'Helenistik diaspora','Jordanien':'Ürdün','Jemen':'Yemen','Sassanidenreich':'Sâsânî İmparatorluğu','Nordarabien':'Kuzey Arabistan','Patmos (laut Offb. 1:9)':'Patmos (Vahiy 1:9’a göre)','Jerusalem':'Kudüs','Tempel von':'tapınağı:','nordöstlich von':'kuzeydoğusu,','südlich von':'güneyi,','nordwestlich von':'kuzeybatısı,','süd-östlich von':'güneydoğusu,','Umgebung von':'çevresi:','Münzstätte':'darphane','unbekannt':'bilinmiyor','wahrscheinlich antikes Israel':'muhtemelen eski İsrail','vermutlich':'muhtemelen','möglicherweise':'belki','Nord-Ost Syrien':'Kuzeydoğu Suriye','Nordost-Syrien':'Kuzeydoğu Suriye','ägyptische Diaspora':'Mısır diasporası','oder':'veya','und':'ve','in Palästina':'Filistin’de','finale Kompilation':'son derleme'}
def tarih(s):
    s=s or ''
    for a,b in TR: s=re.sub(a,b,s)
    for a,b in [(r'yazıya geçirildi (im )?sonra (\d+ MS)',r'\2 sonrası yazıya geçirildi'),(r'yazıya geçirildi im (\S+ yy\. MS)',r'\1 yazıya geçirildi'),(r'\b(başı|ortası|sonu|son üçte biri|\d\. yarısı) (\d+\.? ?(?:- ?\d+\. )?yy\.(?: MÖ| MS)?)',r'\2 \1'),(r'\bnoch ',''),(r'\bzwischen (\d+)-(\d+)',r'\1-\2'),(r'son redaksiyon zwischen',r'son redaksiyon'),(r'Teile (.*?) Jd\.',r'bazı kısımları \1 yy.'),(r'\(önce Abfassung Clemensbriefes 96 MS\)','(96 MS’deki Clemens mektubundan önce)'),(r'Aus saltanatı: sabäischen Königs','Sebe kralı'),(r' Šāpūr II\.',', II. Şapur'),(r'redaksiyon risaleler ancak MS','risalelerin redaksiyonu MS'),(r'yak\. 1\. 2\. yy\.','1.-2. yy. geçişi'),(r'\s+',' ')]: s=re.sub(a,b,s)
    s=re.sub(r'\s+,',',',s)
    return s.strip(' ,')
def yer(s):
    s=(s or '').strip()
    for a in sorted(YER,key=len,reverse=True): s=s.replace(a,YER[a])
    for a,b in [(r'Aṭ-Ṭāʾif \(Ḥiǧāz\)','Tâif (Hicaz)'),(r'Nisibis ?/ ?Edessa|Nisibis veya Edessa','Nusaybin veya Urfa'),(r'\bEdessa','Urfa (Edessa)'),(r'\bNisibis','Nusaybin'),(r'Jh\.','yy.'),(r'(\d+) ?km (\S+), Sanaa',r'San‘a’nın \1 km \2'),(r'(\d+) ?km (\S+), Damaskus',r'Şam’ın \1 km \2'),(r'(\d+) ?km (\S+), Ardabīl',r'Erdebil’in \1 km \2'),(r'Sanaa','San‘a'),(r'Qaryat al-Fāw','Karyetü’l-Fâv'),(r'Maʾrib|Marib','Me’rib'),(r'Caesarea','Kayserya'),(r'Karthago','Kartaca'),(r'darphane (.*)',r'\1 darphanesi'),(r'çevresi: (.*)',r'\1 çevresi'),(r'Ẓafār','Zafâr'),(r'Mabbūg','Mabbug (Menbic)'),(r' \?','?')]: s=re.sub(a,b,s)
    return s
GEL=[('yahudi','Yahudi geleneği',[('tanah','Tanah (İbranî Kitab-ı Mukaddes)'),('apokrif','Apokrif ve pseudepigrafik eserler'),('rabbani','Talmud, Midraş ve Targum'),('helenistik','Helenistik Yahudi yazarlar'),('liturji','Liturji ve yazıtlar'),('diger','Diğer')]),
     ('hristiyan','Hristiyan geleneği',[('yeniahit','Yeni Ahit'),('apokrif','Apokrif İnciller ve efsaneler'),('patristik','Kilise babaları ve Süryani edebiyatı'),('liturji','Dua, ilahi ve liturji')]),
     ('arap','Câhiliye Arap geleneği',[('siir','Şiir'),('yazit','Yazıtlar ve belgeler')]),
     ('iran','İran dinleri',[('zerdust','Zerdüştî metinler (Avesta ve Pehlevî)'),('maniheist','Maniheist metinler'),('yazit','Yazıtlar ve sikkeler')]),
     ('antik','Antik Yakın Doğu ve Greko-Romen dünya',[('yunanroma','Yunan ve Roma yazarları, sikkeler'),('mezopotamya','Mezopotamya')])]
DIL={'Aramäisch/Hebräisch':'Aramice/İbranice','Mittelpersisch (Pahlavī)':'Orta Farsça (Pehlevî)','Sogdisch':'Soğdca','Sumerisch':'Sümerce','Altkirchenslawisch':'Eski Kilise Slavcası','Altäthiopisch (Gəʿəz)':'Ge‘ez','Altäthiopisch':'Ge‘ez','Awestisch':'Avestaca','Aramäisch':'Aramice','Aramäisch (Palmyrenisch)':'Palmira Aramicesi','Altnordarabisch':'Kuzey Arapçası (Safâ)','Altsüdarabisch':'Güney Arapçası'}
def stem(t): return re.sub(r'[\s,:]*(bölüm\s*)?[\dIVXL][\dIVXL.,:;\s\-–ab]*(\(.*\))?$','',t).strip() or t
out=[]
for x in d:
    m=json.load(open(f"{SITE}/k6/m/{x['id']}.json"))
    tan=[k for k in ('sefaria','lxx','sblgnt','pesitta','syrnt') if m.get(k)]
    out.append({'id':x['id'],'ad':x['ad'],'asil':x['baslik'],'eser':stem(x['ad']),'g':x['gelenek'],'a':x['alt'],'dil':DIL.get(m.get('dil'),m.get('dil')) or DIL.get(x['dil_ad'],x['dil_ad']),
      'tarih':tarih(m.get('tarih')),'yer':yer(m.get('yer')),'yazar':x['yazar_tr'],'ay':len(m.get('ayetler',[])),'tanik':tan,'ceviri':[k for k in ('ceviri_de','ceviri_en') if m.get(k)]})
def nat(s): return [int(t) if t.isdigit() else t for t in re.split(r'(\d+)',s)]
out.sort(key=lambda e:nat(e['ad']))
json.dump({'version':1,'tur':'dinler','gelenekler':[{'k':k,'ad':a,'alanlar':[{'k':q,'ad':b} for q,b in al]} for k,a,al in GEL],'metinler':out,
  'not':'Metinler ve Kur’an’la paralellik tespitleri Corpus Coranicum (TUK, CC BY 4.0) kaynaklıdır; Kitab-ı Mukaddes tanıkları Sefaria, LXX (Rahlfs), SBLGNT ve Peşitta/ETCBC’den. Gelenek ve alan sınıflaması ile Türkçe künyeler vahiy++ tarafından yapılmıştır.'},
  open(f'{SITE}/kutuphane/dinler.json','w'),ensure_ascii=False,separators=(',',':'))
print(len(out), collections.Counter(e['g'] for e in out), len(set((e['a'],e['eser']) for e in out)),'eser')
for e in out[::60]: print(e['ad'],'|',e['eser'],'|',e['tarih'],'|',e['yer'],'|',e['dil'])
